type Seq[V any] func(yield func(V) bool)

func Count(n int) iter.Seq[int] {
  return func(yield func(int) bool) {
    for i := 0; i < n; i++ {
      if !yield(i) {
        return
      }
    }
  }
}

example:
func Count(n int) iter.Seq[int] {
  return func(yield func(int) bool) {
    for i := 0; i < n; i++ {
      if !yield(i) {
        return
      }
    }
  }
}

for i := range Count(5) {
  if i == 3 {
    break   // يستدعي yield(false) داخليًا فيوقف Count فورًا
  }
  fmt.Println(i)   // 0 1 2
}

func OnlyAdults(m map[string]int) iter.Seq2[string, int] {
  return func(yield func(string, int) bool) {
    for name, age := range maps.All(m) {
      if age >= 18 {
        if !yield(name, age) {
          return
        }
      }
    }
  }
}

for name, age := range OnlyAdults(ages) {
  fmt.Println(name, age)
}

