func TestRetryWithBackoff(t *testing.T) {
  synctest.Test(t, func(t *testing.T) {
    start := time.Now()
    err := RetryWithBackoff(3, func() error { return errors.New("فشل") })
    if err == nil {
      t.Fatal("توقّعت فشلًا بعد كل المحاولات")
    }
    t.Log(time.Since(start))   // يمرّ زمن المحاولات المتكرّرة فورًا، بلا انتظار حقيقي
  })
}

func TestBackgroundUpdate(t *testing.T) {
  synctest.Test(t, func(t *testing.T) {
    done := false
    go func() {
      done = true
    }()
    synctest.Wait()   // ينتظر حتى تتوقّف الـ goroutine أعلاه فعليًا
    if !done {
      t.Fatal("توقّعت أن تكتمل الـ goroutine قبل Wait")
    }
  })
}

